// Daftar variasi Subjek Email
const subjects = [
  `Halo ${$json.Nama}, ada pesan hangat dari KoperAI ☕`,
  `Cek yuk! Pengingat Kas Mingguan untuk ${$json.Nama}`,
  `Semangat Senin! Titip iuran kasnya ya, ${$json.Nama}`,
  `Update Koperasi: Investasi kecil kita hari ini, ${$json.Nama}`
];

// Daftar variasi Kalimat Pembuka
const openings = [
  "Semoga harimu menyenangkan!",
  "Apa kabar hari ini? Semoga sehat selalu.",
  "Sambil santai sejenak, ada info sedikit nih.",
  "Tetap semangat menjalankan aktivitas ya!"
];

// Daftar Kutipan/Quotes Motivasi
const quotes = [
  "Sedikit demi sedikit, lama-lama menjadi bukit.",
  "Kebersamaan adalah awal dari kesuksesan.",
  "Gotong royong membuat beban terasa ringan.",
  "Menabung hari ini, tersenyum di masa depan."
];

// Logika Pengacak (Randomizer)
const randomSubject = subjects[Math.floor(Math.random() * subjects.length)];
const randomOpening = openings[Math.floor(Math.random() * openings.length)];
const randomQuote = quotes[Math.floor(Math.random() * quotes.length)];

// Menyusun Pesan Lengkap
const messageBody = `
  Halo <b>${$json.Nama}</b>,<br><br>
  ${randomOpening}<br><br>
  Hanya ingin mengingatkan untuk iuran kas koperasi minggu ini sebesar <b>Rp 10.000</b>. 
  Pembayaran bisa dilakukan melalui bendahara atau transfer seperti biasa.<br><br>
  <i>"${randomQuote}"</i><br><br>
  Salam hangat,<br>
  <b>Admin KoperAI</b>
`;

// Output data ke node selanjutnya (Gmail)
return {
  subject: randomSubject,
  message: messageBody
};

// 1. Ambil data dari node sebelumnya (Webhook/Validator)
const nama = $json.nama_bayar;
const email = $json.email_bayar;
