const tanggal = new Date().toLocaleDateString('id-ID', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
});

// 2. Buat ID Transaksi acak untuk kesan profesional
const transactionId = "KPR-" + Math.floor(Math.random() * 1000000);

// 3. Daftar variasi pesan terima kasih agar tidak kaku
const pesanKeren = [
    "Kontribusi Anda hari ini adalah langkah besar untuk kesejahteraan kita bersama.",
    "Terima kasih telah menjadi anggota yang disiplin dan menginspirasi.",
    "Investasi kecil Anda hari ini akan membuahkan hasil besar di masa depan.",
    "Semangat gotong royong Anda sungguh luar biasa!"
];
const randomPesan = pesanKeren[Math.floor(Math.random() * pesanKeren.length)];

// 4. Susun Subjek Email
const subjectEmail = `Bukti Pembayaran Kas Lunas - ${nama} (${transactionId})`;

// 5. Susun Isi Email (HTML)
const htmlBody = `
<div style="font-family: Arial, sans-serif; border: 1px solid #ddd; padding: 20px; border-radius: 10px; max-width: 500px;">
    <h2 style="color: #27ae60; text-align: center;">KWITANSI DIGITAL</h2>
    <hr>
    <p>Halo <b>${nama}</b>,</p>
    <p>Pembayaran kas mingguan Anda telah kami terima dan tercatat di sistem <b>KoperAI</b>.</p>

    <table style="width: 100%; background: #f9f9f9; padding: 10px; border-radius: 5px;">
        <tr><td>ID Transaksi</td><td>: <b>${transactionId}</b></td></tr>
        <tr><td>Tanggal</td><td>: ${tanggal}</td></tr>
        <tr><td>Nominal</td><td>: <b>Rp ${parseInt(nominal).toLocaleString('id-ID')}</b></td></tr>
        <tr><td>Status</td><td>: <span style="color: green; font-weight: bold;">LUNAS</span></td></tr>
    </table>

    <p style="font-style: italic; color: #555; margin-top: 20px;">
        "${randomPesan}"
    </p>

    <hr>
    <p style="font-size: 12px; color: #888; text-align: center;">
        Email ini dihasilkan otomatis oleh sistem KoperAI.<br>
        Simpan email ini sebagai bukti pembayaran yang sah.
    </p>
</div>
`;

// 6. Output untuk dikirim ke Node Gmail
return {
    to_email: email,
    subject: subjectEmail,
    message_html: htmlBody,
    transaction_id: transactionId
};

